-- FamilArea V2 -- email-bound invitations for Timeline Albums.
-- One verified email is one distinct user identity.  No contact/account links.
begin;
create table public.memory_share_invitations (
 id uuid primary key default gen_random_uuid(), memory_id uuid not null references public.memories(id) on delete cascade,
 owner_account_id uuid not null references public.accounts(id) on delete restrict, recipient_contact_id uuid not null,
 recipient_email text not null check(recipient_email=public.normalize_contact_email(recipient_email)), token_hash text not null unique check(token_hash~'^[0-9a-f]{64}$'),
 status text not null default 'pending' check(status in('pending','accepted','declined','cancelled','revoked','expired')),
 delivery_status text not null default 'pending' check(delivery_status in('pending','sent','failed')), delivery_attempted_at timestamptz, delivery_error_code text,
 created_at timestamptz not null default now(), expires_at timestamptz not null default(now()+interval '14 days'), accepted_at timestamptz,
 accepted_by_account_id uuid references public.accounts(id) on delete set null, accepted_collaboration_id uuid references public.memory_collaborations(id) on delete set null,
 declined_at timestamptz, cancelled_at timestamptz, revoked_at timestamptz, expired_at timestamptz,
 foreign key(recipient_contact_id,owner_account_id) references public.contacts(id,owner_account_id) on delete restrict, check(owner_account_id<>accepted_by_account_id), check(expires_at>created_at),
 check((status='accepted')=(accepted_at is not null and accepted_by_account_id is not null and accepted_collaboration_id is not null)), check((status='declined')=(declined_at is not null)), check((status='cancelled')=(cancelled_at is not null)), check((status='revoked')=(revoked_at is not null)), check((status='expired')=(expired_at is not null))
);
create unique index memory_share_invitations_one_pending_email_idx on public.memory_share_invitations(memory_id,recipient_email) where status='pending';
create index memory_share_invitations_owner_memory_idx on public.memory_share_invitations(owner_account_id,memory_id,created_at desc);
create index memory_share_invitations_recipient_pending_idx on public.memory_share_invitations(recipient_email,expires_at,created_at desc) where status='pending';
alter table public.memory_share_invitations enable row level security; revoke all on public.memory_share_invitations from public,anon,authenticated;
create function public.hash_memory_share_invitation_token(p_token text) returns text language sql immutable set search_path=public,extensions,pg_temp as $$ select encode(extensions.digest(convert_to(coalesce(p_token,''),'UTF8'),'sha256'),'hex') $$;
create function public.search_my_memory_share_contacts(p_memory_id uuid,p_query text) returns setof jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare v_owner uuid:=public.require_current_account(); v_query text:=lower(btrim(coalesce(p_query,''))); begin if v_query='' then return; end if; if not exists(select 1 from public.memories where id=p_memory_id and owner_account_id=v_owner) then raise exception 'permission denied'; end if; return query select jsonb_build_object('contact_id',c.id,'display_name',nullif(btrim(concat_ws(' ',c.first_name,c.last_name)),''),'recipient_email',e.email) from public.contacts c join lateral(select public.normalize_contact_email(cm.value) email from public.contact_methods cm where cm.contact_id=c.id and cm.method_type='email' and public.normalize_contact_email(cm.value)~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' order by cm.is_primary desc,cm.id limit 1)e on true where c.owner_account_id=v_owner and(lower(btrim(concat_ws(' ',c.first_name,c.last_name))) like '%'||v_query||'%' or e.email like '%'||v_query||'%') order by lower(btrim(concat_ws(' ',c.first_name,c.last_name))),c.id limit 20; end $$;
create function public.create_memory_share_invitation(p_memory_id uuid,p_contact_id uuid,p_token_hash text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_owner uuid:=public.require_current_account(); v_email text; v_owner_email text; v_sender text; v public.memory_share_invitations%rowtype; begin if p_memory_id is null or p_contact_id is null or coalesce(p_token_hash,'')!~'^[0-9a-f]{64}$' then raise exception 'memory share invitation unavailable'; end if; if (select count(*) from public.memory_share_invitations i where i.owner_account_id=v_owner and i.created_at>now()-interval '1 hour')>=20 then raise exception 'memory share invitation rate limit exceeded'; end if; perform 1 from public.memories where id=p_memory_id and owner_account_id=v_owner for update; if not found then raise exception 'permission denied'; end if; select public.normalize_contact_email(cm.value) into v_email from public.contacts c join public.contact_methods cm on cm.contact_id=c.id and cm.method_type='email' where c.id=p_contact_id and c.owner_account_id=v_owner and public.normalize_contact_email(cm.value)~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' order by cm.is_primary desc,cm.id limit 1 for update of c; if v_email is null then raise exception 'memory share invitation email unavailable'; end if; select public.normalize_contact_email(u.email) into v_owner_email from public.accounts a join auth.users u on u.id=a.auth_user_id where a.id=v_owner and u.email_confirmed_at is not null; if v_owner_email is null then raise exception 'verified sender email required'; end if; if v_email=v_owner_email then raise exception 'cannot invite memory owner'; end if; if exists(select 1 from public.memory_collaborations mc join public.accounts a on a.id=mc.recipient_account_id join auth.users u on u.id=a.auth_user_id where mc.memory_id=p_memory_id and mc.status in('pending','accepted') and u.email_confirmed_at is not null and public.normalize_contact_email(u.email)=v_email) then raise exception 'active memory collaboration already exists'; end if; insert into public.memory_share_invitations(memory_id,owner_account_id,recipient_contact_id,recipient_email,token_hash) values(p_memory_id,v_owner,p_contact_id,v_email,p_token_hash)returning * into v; select coalesce(o.name,nullif(btrim(concat_ws(' ',p.first_name,p.last_name)),''),'Un utente FamilArea')into v_sender from public.accounts a left join public.organizations o on o.account_id=a.id left join public.profiles p on p.account_id=a.id where a.id=v_owner; return jsonb_build_object('invitation_id',v.id,'recipient_email',v.recipient_email,'sender_name',v_sender,'expires_at',v.expires_at); exception when unique_violation then raise exception 'pending memory share invitation already exists'; end $$;
create function public.get_memory_share_invitation_management(p_memory_id uuid) returns setof jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$ declare v_owner uuid:=public.require_current_account(); begin if not exists(select 1 from public.memories where id=p_memory_id and owner_account_id=v_owner)then raise exception 'permission denied';end if; return query select jsonb_build_object('invitation_id',i.id,'contact_id',i.recipient_contact_id,'recipient_email',i.recipient_email,'status',i.status,'delivery_status',i.delivery_status,'created_at',i.created_at,'expires_at',i.expires_at,'accepted_at',i.accepted_at,'declined_at',i.declined_at,'cancelled_at',i.cancelled_at,'revoked_at',i.revoked_at,'expired_at',i.expired_at)from public.memory_share_invitations i where i.memory_id=p_memory_id order by i.created_at desc,i.id; end $$;
create function public.cancel_memory_share_invitation(p_id uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare v_owner uuid:=public.require_current_account(); begin update public.memory_share_invitations set status='cancelled',cancelled_at=now()where id=p_id and owner_account_id=v_owner and status='pending';if not found then raise exception 'memory share invitation not found or not cancellable';end if;end $$;
create function public.get_memory_share_invitation_context(p_token text) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$ declare v public.memory_share_invitations%rowtype;begin select * into v from public.memory_share_invitations where token_hash=public.hash_memory_share_invitation_token(p_token);if not found or v.status<>'pending' or v.expires_at<=now()then raise exception 'memory share invitation unavailable';end if;return jsonb_build_object('recipient_email',v.recipient_email,'expires_at',v.expires_at);end $$;
create function public.accept_my_memory_share_invitation(p_token text) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_account uuid:=public.require_current_account();v_email text;v public.memory_share_invitations%rowtype;v_collab uuid;begin select public.normalize_contact_email(u.email)into v_email from public.accounts a join auth.users u on u.id=a.auth_user_id where a.id=v_account and a.auth_user_id=auth.uid()and a.account_type in('personal','organization')and u.email_confirmed_at is not null;if v_email is null then raise exception 'verified recipient email required';end if;select * into v from public.memory_share_invitations where token_hash=public.hash_memory_share_invitation_token(p_token)for update;if not found then raise exception 'memory share invitation unavailable';end if;if v.status='pending'and v.expires_at<=now()then update public.memory_share_invitations set status='expired',expired_at=now()where id=v.id;raise exception 'memory share invitation expired';end if;if v.status<>'pending'or v.recipient_email<>v_email then raise exception 'memory share invitation unavailable';end if;insert into public.memory_collaborations(memory_id,owner_account_id,recipient_account_id,status,accepted_at)values(v.memory_id,v.owner_account_id,v_account,'accepted',now())returning id into v_collab;update public.memory_share_invitations set status='accepted',accepted_at=now(),accepted_by_account_id=v_account,accepted_collaboration_id=v_collab where id=v.id;return v_collab;end $$;
create function public.decline_my_memory_share_invitation(p_token text) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare v_account uuid:=public.require_current_account();v_email text;v public.memory_share_invitations%rowtype;begin select public.normalize_contact_email(u.email)into v_email from public.accounts a join auth.users u on u.id=a.auth_user_id where a.id=v_account and a.auth_user_id=auth.uid()and u.email_confirmed_at is not null;if v_email is null then raise exception 'verified recipient email required';end if;select * into v from public.memory_share_invitations where token_hash=public.hash_memory_share_invitation_token(p_token)for update;if not found or v.status<>'pending'or v.expires_at<=now()or v.recipient_email<>v_email then raise exception 'memory share invitation unavailable';end if;update public.memory_share_invitations set status='declined',declined_at=now()where id=v.id;end $$;
create function public.mark_memory_share_invitation_delivery(p_id uuid,p_status text,p_error text default null) returns void language plpgsql security definer set search_path=public,pg_temp as $$ begin if p_status not in('sent','failed')then raise exception 'invalid memory share delivery status';end if;update public.memory_share_invitations set delivery_status=p_status,delivery_attempted_at=now(),delivery_error_code=case when p_status='failed'then nullif(left(btrim(coalesce(p_error,'')),80),'')else null end where id=p_id and status='pending';if not found then raise exception 'memory share invitation unavailable';end if;end $$;
create function public.revoke_memory_share_invitation(p_id uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$

declare v_owner uuid:=public.require_current_account();v public.memory_share_invitations%rowtype;begin select * into v from public.memory_share_invitations where id=p_id and owner_account_id=v_owner and status='accepted' for update;if not found then raise exception 'memory share invitation not found or not revocable';end if;update public.memory_collaborations set status='revoked',revoked_at=now()where id=v.accepted_collaboration_id and owner_account_id=v_owner and status='accepted';if not found then raise exception 'memory share invitation collaboration unavailable';end if;update public.memory_share_invitations set status='revoked',revoked_at=now()where id=v.id;end $$;

alter table public.memory_share_invitations owner to postgres; alter function public.hash_memory_share_invitation_token(text)owner to postgres;alter function public.search_my_memory_share_contacts(uuid,text)owner to postgres;alter function public.create_memory_share_invitation(uuid,uuid,text)owner to postgres;alter function public.get_memory_share_invitation_management(uuid)owner to postgres;alter function public.cancel_memory_share_invitation(uuid)owner to postgres;alter function public.revoke_memory_share_invitation(uuid)owner to postgres;alter function public.get_memory_share_invitation_context(text)owner to postgres;alter function public.accept_my_memory_share_invitation(text)owner to postgres;alter function public.decline_my_memory_share_invitation(text)owner to postgres;alter function public.mark_memory_share_invitation_delivery(uuid,text,text)owner to postgres;
revoke all on function public.hash_memory_share_invitation_token(text)from public,anon,authenticated;revoke all on function public.search_my_memory_share_contacts(uuid,text),public.create_memory_share_invitation(uuid,uuid,text),public.get_memory_share_invitation_management(uuid),public.cancel_memory_share_invitation(uuid),public.revoke_memory_share_invitation(uuid),public.accept_my_memory_share_invitation(text),public.decline_my_memory_share_invitation(text)from public,anon,authenticated;revoke all on function public.get_memory_share_invitation_context(text)from public,anon,authenticated;revoke all on function public.mark_memory_share_invitation_delivery(uuid,text,text)from public,anon,authenticated;grant execute on function public.mark_memory_share_invitation_delivery(uuid,text,text)to service_role;
commit;
